<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {request,ApiError} from '../lib/api';
import {workDateParts} from '../lib/work-tasks';
import WorkDatePicker from './WorkDatePicker.vue';
import {activities,foods,bmi,bmiLabel,foodCalories,exerciseCalories,weightDays,type SlimEntry} from '../lib/slim';
const activityCards=[{icon:'🚶',title:'散步摸鱼',detail:'平地走路 · 约4.5–5公里/小时'},{icon:'👟',title:'快走放风',detail:'平地快走 · 约5.6–6.3公里/小时'},{icon:'🏃',title:'慢跑清空脑袋',detail:'自选配速 · 按实际体感活动'},{icon:'🚲',title:'骑车兜个风',detail:'休闲骑行 · 低于16公里/小时'},{icon:'🌿',title:'伸个懒腰',detail:'轻度拉伸 · 给身体松松绑'}];
const props=defineProps<{foreground:boolean}>();
const emit=defineEmits<{(e:'auth-expired'):void}>();
const today=()=>workDateParts(new Date().toISOString()).day;
const day=ref(today()),entries=ref<SlimEntry[]>([]),gender=ref('male'),height=ref(''),bodyWeight=ref('');
const kind=ref<'food'|'exercise'|'weight'>('food'),name=ref(''),grams=ref('100'),rate=ref(''),minutes=ref('30'),activity=ref(0),query=ref('');
const error=ref(''),busy=ref(false),loading=ref(false),loaded=ref(false),message=ref(''),page=ref(1);
let disposed=false,seq=0,pendingID='';
const catalog=computed(()=>foods.filter(f=>f.name.includes(query.value.trim())));
const selected=computed(()=>entries.value.filter(e=>e.day===day.value));
const intake=computed(()=>selected.value.filter(e=>e.kind==='food').reduce((s,e)=>s+e.calories,0));
const burn=computed(()=>selected.value.filter(e=>e.kind==='exercise').reduce((s,e)=>s+e.calories,0));
const duration=computed(()=>selected.value.filter(e=>e.kind==='exercise').reduce((s,e)=>s+e.quantity,0));
const weights=computed(()=>weightDays(entries.value));
const recentWeights=computed(()=>weights.value.slice(-14));
const change=computed(()=>weights.value.length>1?weights.value[weights.value.length-1].weight-weights.value[0].weight:null);
const weightKg=computed(()=>Number(bodyWeight.value)/2);
const bmiValue=computed(()=>bmi(Number(height.value),weightKg.value));
const preview=computed(()=>kind.value==='food'?foodCalories(Number(grams.value),Number(rate.value)):exerciseCalories(Number(minutes.value),weightKg.value,activities[activity.value].met));
const shown=computed(()=>selected.value.slice(0,page.value*20));
function fail(e:unknown){if(disposed)return;if(e instanceof ApiError&&e.status===401)emit('auth-expired');if(!(e instanceof ApiError&&e.status===0))error.value=(e as Error).message;}
async function load(){if(busy.value)return;const n=++seq;loading.value=true;error.value='';try{const d=await request<{profile:{gender:string;height:number};entries:SlimEntry[]}>('/slim');if(disposed||n!==seq)return;entries.value=d.entries;if(!loaded.value){gender.value=d.profile.gender||'male';height.value=d.profile.height?String(d.profile.height):'';const w=weightDays(d.entries);bodyWeight.value=w.length?String(w[w.length-1].weight*2):'';loaded.value=true;}}catch(e){fail(e);}finally{if(!disposed&&n===seq)loading.value=false;}}
function pickFood(f:typeof foods[number]){name.value=f.name;rate.value=String(f.kcal);}
watch([kind,day,name,grams,rate,minutes,activity,bodyWeight],()=>{pendingID='';message.value='';},{flush:'sync'});
watch(day,()=>page.value=1);
async function saveProfile(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await request('/slim/profile','POST',{gender:gender.value,height:Number(height.value)});if(!disposed)message.value='档案存好了，身体不参加绩效考核。';}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
async function save(){if(busy.value||!loaded.value)return;error.value='';message.value='';if(!day.value){error.value='先选记录日期。';return;}if(kind.value==='food'&&(!name.value.trim()||!rate.value.trim()||!grams.value.trim())){error.value='填写食物、克数和每100克热量。';return;}if(kind.value!=='food'&&!bodyWeight.value.trim()){error.value='先填写下方的体重（斤），运动估算也需要它。';return;}
 busy.value=true;seq++;loading.value=false;pendingID=pendingID||('slim_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2));
 try{const e=await request<SlimEntry>('/slim/entries','POST',{id:pendingID,day:day.value,kind:kind.value,name:kind.value==='food'?name.value:kind.value==='weight'?'体重打卡':activities[activity.value].name,quantity:Number(kind.value==='food'?grams.value:minutes.value),rate:Number(rate.value),weight:weightKg.value});if(disposed)return;entries.value=[e,...entries.value.filter(x=>x.id!==e.id)].sort((a,b)=>b.day.localeCompare(a.day));pendingID='';message.value=kind.value==='food'?'投喂已登记，吃饭不是犯错。':kind.value==='exercise'?'活动已入账，离开工位也算一种胜利。':'记录好了，看长期趋势就行。';}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
function remove(e:SlimEntry){uni.showModal({title:'删除这条记录？',content:e.day+' · '+e.name,success:async result=>{if(!result.confirm||disposed||busy.value)return;busy.value=true;seq++;try{await request('/slim/entries/'+e.id+'/delete','POST',{});if(!disposed)entries.value=entries.value.filter(x=>x.id!==e.id);}catch(err){fail(err);}finally{if(!disposed)busy.value=false;}}});}
function barHeight(w:number){const all=recentWeights.value.map(e=>e.weight),low=Math.min(...all),high=Math.max(...all);return (high===low?45:20+(w-low)/(high-low)*55)+'px';}
watch(()=>props.foreground,v=>{if(v)load();});onMounted(load);onBeforeUnmount(()=>{disposed=true;seq++;});
</script>
<template>
<view class="slim-lab">
 <view class="hero"><view><text class="eyebrow">BODY / 牛马身体观察站</text><text class="title">瘦瘦研究所</text><text class="subtitle">老板的饼不计入热量，自己的饭要好好吃。</text></view><view class="stamp">认真吃饭<text>合理摸鱼</text></view></view>
 <view class="date-line"><WorkDatePicker v-model="day" title="翻到哪天的研究日志？" min="2020-01-01" :max="today()" :clearable="false"/><button @click="day=today()">回到今天</button><button :disabled="busy||loading" @click="load">{{loading?'读取中…':'刷新'}}</button></view>
 <view class="metrics"><view><text>投喂到账</text><text class="number">{{Math.round(intake)}}<text> kcal</text></text><text>已记录的食物</text></view><view><text>活动消耗 · 估算</text><text class="number">{{Math.round(burn)}}<text> kcal</text></text><text>活动了 {{duration}} 分钟</text></view><view><text>体重变化 · 全部记录</text><text class="number">{{change===null?'—':(change>0?'+':'')+(change*2).toFixed(1)}}<text> 斤</text></text><text>{{change===null?'记录两天后查看':weights[0].day+' 至 '+weights[weights.length-1].day}}</text></view></view>
 <text class="note">摄入与运动分别记账；运动消耗包含运动期间静息消耗，并非全天消耗。两数相减不等于热量缺口，体重变化也不等于脂肪变化。</text>
 <view class="columns"><view class="card journal"><text class="section">今天，对自己做了什么？</text><view class="tabs"><button :class="{active:kind==='food'}" @click="kind='food'">🍚 投喂</button><button :class="{active:kind==='exercise'}" @click="kind='exercise'">🚶 活动</button><button :class="{active:kind==='weight'}" @click="kind='weight'">⚖ 体重</button></view>
 <template v-if="kind==='food'"><input v-model="query" class="input" placeholder="搜常见食物，如米饭、鸡蛋"/><view class="chips"><button v-for="f in catalog" :key="f.name" @click="pickFood(f)">{{f.name}}</button><text v-if="!catalog.length" class="note">没找到？在下面自填名称和包装热量。</text></view><text class="label">食物名称</text><input v-model="name" :maxlength="80" class="input" placeholder="例如：午饭的米饭"/><view class="fields"><view><text class="label">吃了多少（克）</text><input v-model="grams" type="digit" class="input" placeholder="100"/></view><view><text class="label">每100克热量（千卡）</text><input v-model="rate" type="digit" class="input" placeholder="按包装或食物表填写"/></view></view><text class="note">快捷食物为可食部分的参考均值，可修改。熟米饭与生米不同；油、酱料需另记。包装若标千焦，除以4.184得到千卡；按克称量，饮料也需确认份量。</text></template>
 <template v-else-if="kind==='exercise'"><text class="label">活动项目</text><view class="activity-options" role="group" aria-label="选择活动项目"><button v-for="(item,index) in activityCards" :key="item.title" :class="['activity-card',{chosen:activity===index}]" :aria-pressed="activity===index" @click="activity=index"><text class="activity-icon">{{item.icon}}</text><view class="activity-copy"><text class="activity-title">{{item.title}}</text><text class="activity-detail">{{item.detail}}</text></view><text class="activity-check">{{activity===index?'✓':''}}</text></button></view><text class="label">持续多久（分钟）</text><input v-model="minutes" type="digit" class="input"/><text class="label">运动时体重（斤）</text><input v-model="bodyWeight" type="digit" class="input" placeholder="例如 130"/><text class="note">使用成人活动 MET 估算；强度、体能和设备会影响实际消耗。</text></template>
 <template v-else><text class="label">今天称到的体重（斤）</text><input v-model="bodyWeight" type="digit" class="input" placeholder="例如 130.4"/><text class="note">尽量在相近条件下称重。当天多次打卡，趋势采用最后一条；波动很正常，不用为数字补偿性少吃或加练。</text></template>
 <view v-if="kind!=='weight'" class="preview">{{kind==='food'?'这次投喂约':'这次活动估算'}} <text>{{Number.isFinite(preview)&&preview>=0?Math.round(preview):'—'}}</text> kcal</view><button class="primary" :disabled="busy||!loaded" @click="save">{{busy?'记录中…':kind==='food'?'收下这份快乐':kind==='exercise'?'记下这次活动':'存下体重观察'}}</button>
 </view><view class="card bmi-card"><text class="eyebrow">身体档案 / BMI</text><text class="section">体重不是绩效</text><view class="fields"><view><text class="label">身高（厘米）</text><input v-model="height" type="digit" class="input" placeholder="例如 170"/></view><view><text class="label">体重（斤）</text><input v-model="bodyWeight" type="digit" class="input" placeholder="例如 130"/></view></view><view class="bmi-result"><text class="bmi-number">{{bmiValue===null?'—':bmiValue.toFixed(1)}}</text><text>{{bmiValue===null?'填入身高体重，即时计算':bmiLabel(bmiValue)}}</text></view><view class="scale"><view/><view/><view/><view/></view><text class="note">偏低 &lt;18.5 · 正常 18.5–&lt;24 · 超重 24–&lt;28 · 肥胖 ≥28</text><text class="note">男女成人使用同一公式：（体重斤 ÷ 2）÷ 身高m²。依据中国成人标准，供18岁及以上非孕期成人参考；BMI不能区分肌肉与脂肪，也不作诊断。</text><button class="secondary" :disabled="busy||!loaded" @click="saveProfile">保存身高</button><text class="note">体重请填斤，例如130斤=65公斤。只算 BMI 不会新增体重记录，点击“体重打卡”再保存。数据仅自己可见。</text></view></view>
 <text v-if="error" class="error" selectable>{{error}}</text><text v-if="message" class="success">{{message}}</text>
 <view class="card"><text class="section">身体的慢镜头</text><text class="note">最近14个有记录的日期 · 每天最后一次体重（斤），柱高仅展示相对变化</text><scroll-view scroll-x><view class="chart"><view v-for="e in recentWeights" :key="e.id" class="bar-cell"><text>{{Number((e.weight*2).toFixed(1))}}</text><view class="bar" :style="{height:barHeight(e.weight)}"/><text>{{e.day.slice(5)}}</text></view></view></scroll-view><text v-if="!recentWeights.length" class="empty">研究员尚未上秤。先记录一次，慢慢观察。</text></view>
 <view class="card"><text class="section">{{day}} · 私人研究日志</text><text v-if="!selected.length" class="empty">{{loading?'正在翻日志…':'今天还没有记录，不代表今天没吃饭哦。'}}</text><view v-for="e in shown" :key="e.id" class="entry"><view><text class="entry-name">{{e.kind==='food'?'🍚':e.kind==='exercise'?'🚶':'⚖'}} {{e.name}}</text><text class="note">{{e.kind==='food'?e.quantity+' g · '+e.rate+' kcal/100g':e.kind==='exercise'?e.quantity+' 分钟 · 当时 '+Number((e.weight*2).toFixed(1))+' 斤':'实际称重'}}</text></view><text class="entry-value">{{e.kind==='weight'?Number((e.weight*2).toFixed(1))+' 斤':Math.round(e.calories)+' kcal'}}</text><button class="delete-entry" :disabled="busy" :aria-label="'删除'+e.name+'记录'" @click="remove(e)"><view class="delete-icon" aria-hidden="true"><view/></view><text>删除</text></button></view><button v-if="shown.length<selected.length" class="secondary" @click="page++">再看20条</button></view>
 <view class="sources"><text>计算依据：国家卫健委《成人体重判定》；2024 Adult Compendium（pacompendium.com）；常见食物为 USDA 等成分表的取整参考值，以实际包装和做法为准。</text><text>这是生活记录，不是减重处方。研究的是好好照顾自己，不是越轻越好。</text></view>
</view>
</template>
<style scoped>
.slim-lab{color:#626b56;max-width:1120px;margin:auto;padding:10px 0 40px}.hero{display:flex;justify-content:space-between;align-items:center;padding:24px 0 28px}.eyebrow{display:block;font-size:11px;letter-spacing:2px;color:#9aab86}.title{display:block;font-size:34px;font-weight:700;margin:10px 0}.subtitle{font-size:14px;color:#879078}.stamp{border:1px solid #b4c49c;border-radius:50%;width:90px;height:90px;display:flex;flex-direction:column;align-items:center;justify-content:center;transform:rotate(9deg);font-size:15px;line-height:1.8}.stamp text{font-size:12px}.date-line{display:flex;align-items:center;gap:10px;margin-bottom:18px}.slim-lab button{margin:0;font-size:12px;line-height:1.6;padding:10px 14px;border-radius:10px;background:#f0f1e7;color:#687354}.slim-lab button::after{border:0}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.metrics>view{min-width:0;overflow-wrap:anywhere;background:#eef1df;border:1px solid #e1e7cd;border-radius:18px;padding:22px;display:flex;flex-direction:column;gap:10px;font-size:12px}.metrics>view:nth-child(2){background:#edf0f2;border-color:#e0e6e9}.metrics>view:nth-child(3){background:#f2ecf5;border-color:#e9dfed}.number{font-size:32px;font-weight:600}.number text{font-size:12px;font-weight:400}.note{display:block;color:#909583;font-size:11px;line-height:1.9;margin-top:10px}.columns{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:18px;margin-top:22px}.card{min-width:0;padding:24px;background:#fffef8;border:1px solid #e5e6d9;border-radius:20px;margin-bottom:20px}.section{display:block;font-size:18px;font-weight:600;margin-bottom:16px}.tabs{display:flex;gap:8px;margin:16px 0}.tabs button{flex:1}.tabs .active{background:#737f5b;color:#fff}.label{display:block;margin:15px 0 8px;font-size:12px}.input{border:1px solid #dedfce;border-radius:10px;padding:12px;background:#fafaf2;font-size:14px;height:23px;color:#586248;box-sizing:content-box}.picker{height:auto;min-height:23px}.fields{display:flex;gap:12px}.fields>view{flex:1;min-width:0}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.chips button{padding:5px 9px;font-size:11px;background:#f4f2e8}.preview{padding:20px 0;font-size:13px}.preview text{font-size:27px;margin:0 8px}.slim-lab .primary{background:#79875d;color:white;width:100%;padding:13px}.slim-lab .secondary{background:#e9eddb;margin-top:16px;width:100%}.bmi-result{display:flex;flex-direction:column;align-items:center;padding:20px 0;gap:8px;font-size:13px}.bmi-number{font-size:64px;font-weight:600;color:#7a8860}.scale{display:flex;height:8px;border-radius:6px;overflow:hidden}.scale view{flex:1;background:#b6cbd2}.scale view:nth-child(2){background:#b5c78f}.scale view:nth-child(3){background:#dfc28c}.scale view:nth-child(4){background:#c8aac1}.error,.success{display:block;padding:16px;margin-bottom:18px;border-radius:12px;font-size:13px}.error{background:#f9eae4;color:#a55544}.success{background:#edf1e0;color:#6b794e}.chart{display:flex;gap:14px;min-height:125px;padding-top:12px;align-items:flex-end}.bar-cell{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:8px;min-width:48px;font-size:11px}.bar{width:20px;background:#bccaa0;border-radius:6px 6px 0 0}.empty{display:block;padding:22px 0;font-size:13px;color:#9a9e90}.entry{display:flex;gap:12px;align-items:center;padding:16px 0;border-top:1px solid #eeeee4}.entry>view{flex:1;min-width:0}.entry-name{font-size:14px;overflow-wrap:anywhere}.entry-value{font-size:14px;white-space:nowrap}.entry button{font-size:11px;padding:6px;background:transparent;color:#a48e80}.sources{font-size:10px;color:#9a9e92;line-height:1.9}.sources text{display:block;margin-top:8px}@media(max-width:760px){.title{font-size:28px}.stamp{width:68px;height:68px;font-size:13px;flex-shrink:0;margin-left:8px}.subtitle{font-size:12px}.columns{grid-template-columns:1fr;gap:0}.metrics{gap:7px}.metrics>view{padding:14px 9px;font-size:10px}.number{font-size:24px}.number text{font-size:10px}.card{padding:18px}.date-line{gap:6px;flex-wrap:wrap}.hero{padding-top:10px}.entry{gap:7px}.entry-value{font-size:12px}}

.activity-options{display:flex;flex-direction:column;gap:9px}.slim-lab .activity-card{display:flex;align-items:center;gap:12px;width:100%;padding:13px 14px;background:#fafaf4;border:1px solid #e5e7da;border-radius:14px;text-align:left;transition:background .15s,border-color .15s;box-sizing:border-box}.activity-icon{display:flex;align-items:center;justify-content:center;width:40px;height:40px;flex-shrink:0;background:#f0f1e6;border-radius:12px;font-size:23px}.activity-copy{flex:1;min-width:0}.activity-title{display:block;font-size:14px;font-weight:600;color:#667252}.activity-detail{display:block;font-size:11px;line-height:1.6;color:#929985;margin-top:3px}.activity-check{display:flex;align-items:center;justify-content:center;width:20px;height:20px;flex-shrink:0;border:1px solid #d7dcc9;border-radius:50%;color:transparent;font-size:12px}.slim-lab .activity-card.chosen{background:#eef2e3;border-color:#a6b88a}.chosen .activity-icon{background:#e0e8ce}.chosen .activity-check{background:#829566;border-color:#829566;color:white}.activity-card:focus-visible{outline:2px solid #829566;outline-offset:3px}@media(hover:hover){.slim-lab .activity-card:hover{border-color:#a6b88a;background:#f1f4e9}}

.slim-lab .entry .delete-entry{display:flex;align-items:center;justify-content:center;gap:7px;min-width:64px;min-height:40px;margin-left:4px;padding:8px 10px;border:1px solid #e6d8d0;border-radius:11px;background:#fcf7f2;color:#a17e6d;font-size:11px;line-height:1.4;flex-shrink:0;box-sizing:border-box;transition:background .15s,border-color .15s}.delete-icon{position:relative;width:11px;height:12px;box-sizing:border-box;border:1.4px solid currentColor;border-top:0;border-radius:0 0 3px 3px;margin-top:3px}.delete-icon::before{content:'';position:absolute;top:-3px;left:-2px;width:12px;border-top:1.4px solid currentColor}.delete-icon::after{content:'';position:absolute;width:4px;height:2px;left:2px;top:-6px;border:1.3px solid currentColor;border-bottom:0;border-radius:2px 2px 0 0}.delete-icon>view{height:6px;width:3px;border-left:1px solid currentColor;border-right:1px solid currentColor;margin:3px auto 0}.slim-lab .entry .delete-entry:active{background:#f1dfd5;border-color:#c8a08c}.delete-entry:focus-visible{outline:2px solid #b68a74;outline-offset:3px}.slim-lab .entry .delete-entry[disabled]{opacity:.4}@media(hover:hover){.slim-lab .entry .delete-entry:hover{background:#f5e9e0;border-color:#d2b4a2}}
</style>
